function validateLogin(email, pw) {
  if (!email) return '이메일을 입력하세요';
  if (isDuplicate(email)) return '이미 가입된 이메일입니다';
  if (pw.length < 8) return '비밀번호가 너무 짧습니다';
  return null;
}

