  if (!/^\d{16}$/.test(cardNumber)) return '카드번호 형식이 올바르지 않습니다';
  return null;
}
function validateExpiry(expiry) {
  if (!/^\d{2}\/\d{2}$/.test(expiry)) return '만료일 형식이 올바르지 않습니다';
  return null;
}
function validateCvc(cvc) {
  if (!/^\d{3}$/.test(cvc)) return 'CVC는 3자리여야 합니다';
  return null;
}

